INSERT INTO `wp_posts` VALUES (2583,1,'2026-06-21 11:26:02','2026-06-21 11:26:02','.megamenu-list ul {list-style:none;}\r\n.megamenu-list ul li {padding:8px 0;line-height:14px}\r\n.megamenu-list ul a:hover {text-decoration:underline;}\r\n.megamenu-list ul .last-link {color:#15a9e3;font-weight:600;}\r\n.megamenu-list ul .last-link:after {background:#15a9e3;\r\n}\r\n\r\n.heading-label {\r\n    margin-left: 8px;\r\n    display: inline-block;\r\n    border-radius: 48px;\r\n    padding: 4px 8px 4px 8px;\r\n    vertical-align: middle;\r\n    top: -1px;\r\n    color: #ffffff;\r\n    background:#39cb74;\r\n    font-size: 12px;\r\n    line-height: 12px;\r\n    text-align: center;\r\n    position: relative;\r\n    left: 0px !important;\r\n    transform: none !important;\r\n    text-transform: none;\r\n}\r\n.footer-logo-column .et-image{max-width:200px;}\r\n\r\n.map-link a .text {text-decoration:underline;}\r\n.map-link a:hover {color:#15a9e3 !important;}\r\n.et-footer .et-mm .sub-menu {\r\n    margin-bottom:0;\r\n}\r\n.slider-button {box-shadow:0 0 16px rgba(0,0,0,0.05) !important;}\r\n.slider-button i {font-size:10px !important;margin-left:4px !important;display:inline-block !important;}\r\nrs-module-wrap,\r\nrs-module-wrap rs-slides,\r\nrs-module-wrap rs-sbg-wrap\r\n{border-radius:10px}\r\n#rev_slider_9_1_wrapper,\r\n#rev_slider_9_1_wrapper rs-slides,\r\n#rev_slider_9_1_wrapper rs-sbg-wrap {\r\n    border-radius:0;\r\n}\r\nrs-module-wrap rs-sbg-wrap {overflow:hidden}\r\n.custom.sr7-arrows {\r\n    border-radius:100px !important;\r\n    background:#ffffff !important;\r\n    transform:scale(1) !important;\r\n    transform-origin:center;\r\n    box-shadow:0 0 16px rgba(0,0,0,0.1);\r\n    transition:background 0.3s ease-out, transform 0.6s cubic-bezier(0.75, -1.27, 0.3, 2.33);\r\n    top:50%;\r\n    margin-top:-20px;\r\n}\r\n.custom.sr7-arrows:before {\r\n    color:#184363 !important;\r\n    transition:color 0.3s;\r\n}\r\n.custom.sr7-arrows:hover {\r\n    background:#184363 !important;\r\n    box-shadow:0 0 16px rgba(0,0,0,0.05);\r\n    transform:scale(1.2) !important;\r\n}\r\n.custom.sr7-arrows:hover:before {\r\n    color:#ffffff !important;\r\n}\r\n.custom.sr7-arrows.sr7-rightarrow {\r\n    left:calc(100% - 64px) !important;\r\n}\r\n.custom.sr7-arrows.sr7-leftarrow {\r\n    left:24px !important;\r\n}\r\n#rev_slider_7_1_wrapper .custom.sr7-arrows.sr7-rightarrow {\r\n    left:calc(100% - 18px) !important;\r\n}\r\n#rev_slider_7_1_wrapper .custom.sr7-arrows.sr7-leftarrow {\r\n    left:-22px !important;\r\n}\r\n.custom .sr7-bullet {\r\n    background:#184363 !important;\r\n    opacity:0.2;\r\n    border-radius:10px !important;\r\n    width:8px !important;\r\n    height:8px !important;\r\n    transform:scale(0.7);\r\n    transform-origin:center;\r\n    transition:background 0.3s ease-out, transform 0.6s cubic-bezier(0.75, -1.27, 0.3, 2.33);\r\n}\r\n.custom .sr7-bullet.selected {\r\n    transform:scale(1);\r\n}\r\n\r\n.footer-clients .grid.et-client-container .et-client {\r\n	border-bottom-color:rgba(255,255,255,0.1);\r\n}\r\n\r\n.footer-tiny-menu .wpb_wrapper * {\r\n    display: inline-block;\r\n    vertical-align: middle;\r\n    color: #56778f !important;\r\n    font-size: 12px;\r\n    line-height: 18px;\r\n    position: relative;\r\n}\r\n.footer-tiny-menu .wpb_wrapper a:hover {color:#184363 !important;}\r\n.footer-tiny-menu .wpb_wrapper *:not(p):after {\r\n    display:inline-block;\r\n    width:1px;\r\n    height:16px;\r\n    margin:0 8px 0 10px;\r\n    background-color:#bdbdbd;\r\n    content:\"\";\r\n    vertical-align:middle;\r\n}\r\n.footer-tiny-menu .wpb_wrapper *:not(p):last-child:after {\r\n    display:none !important;\r\n}\r\n.z-index-15 {z-index:15}\r\n#megamenu-1310, #megamenu-1320 {overflow:visible}\r\n.home-3-megamenu-row {border-radius:0 0 10px 10px;}\r\n.banner-list a:hover {text-decoration:underline;}\r\n.corner-border-radius {border-radius:0 0 10px 0;}\r\n.corner-border-radius-2 {border-radius:0 10px 10px 0;}\r\n\r\n.header-